function kleeneNot(v){
  if(v==='T') return 'F';
  if(v==='F') return 'T';
  return 'U';
}
function kleeneOr(a,b){
  const order={F:0, U:1, T:2};
  return order[a] >= order[b] ? a : b;
}
function implies(a,b){
  // a -> b = (¬a) ∨ b
  return kleeneOr(kleeneNot(a), b);
}
